/**
 * @description
 */

let BonusType = {
    Coin: 1,
    Double: 2,
    JackpotWheel: 3,
};

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {},

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    StartMove: function () {
        this._super();
    },

    ShowById(id, data) {
        this._super(id, data);
        this.showBonus();
    },

    //停止动画
    playStopAnimation(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (id !== cfg.bonusId) {
            this._super();
        } else {
            this._state = "stop";
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            // 查找数据然后判断播放哪个动画
            this.node.zIndex = 200 - this._symbolIdx  + this._reelIdx*10;
            let nodeSp = this._showNode.getComponent(sp.Skeleton)
            if(nodeSp){
                nodeSp.clearTracks();
                nodeSp.setToSetupPose();
                if (this._data.isJackpot) {
                    nodeSp.setAnimation(0, "HuoLun_Jackpot_Intro", false);
                    nodeSp.addAnimation(0, "HuoLun_Jackpot_Loop", true);
                } else if (this._data.isSuper) {
                    nodeSp.setAnimation(0, "HuoLun_Super_Intro", false);
                    nodeSp.addAnimation(0, "HuoLun_Super_Loop", true);
                } else {
                    nodeSp.setAnimation(0, "HuoLun_X" + this._data.mult + "_Intro", false);
                    nodeSp.addAnimation(0, "HuoLun_X"+ this._data.mult + "_Loop", true);
                }
            }
        }
    },

    showWheelCoin(num) {
        let nodeSp = this._showNode.getComponent(sp.Skeleton)
        if(nodeSp){
            nodeSp.setAnimation(0, "HuoLun_yingfen_Intro2", false);
            nodeSp.setCompleteListener(()=>{
                nodeSp.setCompleteListener(null);
                cc.find("coin", this._showNode).active = true;
                cc.find("coin", this._showNode).getComponent(cc.Label).string = Global.formatNumShort(num, 0);
                nodeSp.setAnimation(0, "HuoLun_Loop1", true);
            });
        }
    },

    playidleAnimation(){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (id !== cfg.bonusId) {
            this._super();
        } else {
            this._state = "idle";
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true
            this.node.zIndex = 200 - this._symbolIdx + this._reelIdx*10;
            isPlay = true
            let nodeSp = this._showNode.getComponent(sp.Skeleton)
            if(nodeSp){
                if (this._data.isJackpot) {
                    nodeSp.setAnimation(0, "HuoLun_Jackpot_Loop", true);
                } else if (this._data.isSuper) {
                    nodeSp.setAnimation(0, "HuoLun_Super_Loop", true);
                } else {
                    nodeSp.setAnimation(0, "HuoLun_X"+ this._data.mult + "_Loop", true);
                }
            }
        }
        return isPlay
    },

    showBonus() {
        if (this._id === cc.vv.gameData.getGameCfg().bonusId) {
            let icon = cc.find("icon", this._showNode)
            let indexs = [2, 3, 5, 8, 10, 15, 30];
            if (this._data && icon) {
                if (this._data.isJackpot) {
                    icon.getComponent("ImgSwitchCmp").setIndex(8);
                } else if (this._data.isSuper) {
                    icon.getComponent("ImgSwitchCmp").setIndex(7);
                } else {
                    icon.getComponent("ImgSwitchCmp").setIndex(indexs.indexOf(this._data.mult));
                }
            } else {
                if (icon) {
                    // let random = ["jackpot", "x2", "x3", "x5", "x8", "x10", "x15", "x30", "super"];
                    // let str = random[Math.floor(Math.random() * random.length)];
                    // icon.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetSpriteFrameByName(str);

                    icon.getComponent("ImgSwitchCmp").setIndex(Math.floor(Math.random() * 9));
                }
            }
        }
    },

    getBonusSpine() {
        return this._showNode.getComponent(sp.Skeleton);
    },

    showNormalBonus() {
        this._state = "normal";

        if(this._showNode){
            this._showNode.active = false
        }
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[this._id] && cfg.symbol[this._id].node){
            this._showNode = cc.find(cfg.symbol[this._id].node,this.node);
            this._showNode.active = true
            cc.find("icon", this._showNode).active = false;
        }
        else{
            console.log("未找到配置id:" + id)
        }
    },
});