/**
 * @description
 */

let JackpotGameSymbol = {
    None: 0,
    Mini: 1,
    Minor: 2,
    Major: 3,
    Mega: 4,
    Grand: 5,
    Gold: 6
};

let animationName = ["Mini", "Minor", "Major", "Grand"];


cc.Class({
    extends: cc.Component,
    properties: {
        rubyCoin: cc.Label,
        amethystCoin: cc.Label,
        sapphireCoin: cc.Label,
        emeraldCoin: cc.Label,
        layout: cc.Node,
        result_node: cc.Node,


        _successCallback: null,
        _canSelect: false,
        _haveOpenReward: null,
        _winCoin: 0,
        _collectGame: null,
    },

    onLoad() {
        this._haveOpenReward = [];
        for (let i = 1; i < 13; i++) {
            let node = cc.find("item_" + i, this.layout);
            node.on(cc.Node.EventType.TOUCH_END, async ()=>{
                if (!this._canSelect) {
                    return;
                }

                if (this._haveOpenReward.indexOf(i) !== -1) {
                    return;
                }

                Global.SlotsSoundMgr.playEffect("koiPick");
                let req = {rtype:3, choiceId: i};
                let result = await cc.vv.gameData.reqSubGame(req);
                if (result.code === 200) {
                    this._canSelect = false;
                    let collectGame = result.data.collectGame;
                    let miniGame = collectGame.roundInfo.miniGame;
                    let choiceId = result.data.choiceId;
                    this._haveOpenReward.push(choiceId);
                    this._collectGame = collectGame;

                    let selectItem = cc.find("item_" + choiceId, this.layout);
                    let spine = cc.find("spine", selectItem).getComponent(sp.Skeleton);
                    let animation = animationName[miniGame.items[choiceId - 1].jackpotId - 1]
                    spine.setAnimation(0, "Coin_Intro_" + animation + "1_EN", false);
                    spine.addAnimation(0, animation + "_Loop_EN", true);

                    if (miniGame.isEnd) {
                        Global.SlotsSoundMgr.playEffect("koiSure");
                        this.endGame(miniGame, choiceId);
                    } else {
                        await cc.vv.gameData.awaitTime(1);

                        this._canSelect = true;
                    }
                }
            });
        }
    },

    async endGame(miniGame, lastChoiceId) {
        for (let j = 1; j < 13; j++) {
            // 所有的翻过来
            let info = miniGame.items[j - 1];
            let node = cc.find("item_" + j, this.layout);
            let spine = cc.find("spine", node).getComponent(sp.Skeleton);
            let animation = animationName[info.jackpotId - 1]
            if (info.jackpotId === miniGame.items[lastChoiceId - 1].jackpotId) {
                spine.setAnimation(0, animation + "_End_EN", true);
            } else {
                if (!info.isOpen) {
                    spine.setAnimation(0, "Coin_Intro_" + animation + "2_EN", false);
                }
            }
        }

        await cc.vv.gameData.awaitTime(1);

        this.popResult(miniGame, lastChoiceId);
    },

    async popResult(miniGame, lastChoiceId) {
        Global.SlotsSoundMgr.playEffect("fgend");
        let animations = ["lv", "honglan", "zi", "hong"];
        this.result_node.active = true;
        let parent = cc.find("parent", this.result_node);

        let diban = cc.find("DT_diban2", parent).getComponent(sp.Skeleton);
        let jackpotId = miniGame.items[lastChoiceId - 1].jackpotId;
        for (let i = 1; i < 5; i++) {
            let title = cc.find("jackpot_title_" + i, parent);
            title.active = i === jackpotId;
        }
        diban.setAnimation(0, "liyu_" + animations[jackpotId - 1], true);

        parent.scale = 0;
        cc.tween(parent)
            .to(0.5, {scale: 1}, {easing: "backOut"})
            .start();

        cc.find("yifenkuang/coin", parent).getComponent(cc.Label).string = Global.FormatNumToComma(miniGame.winCoin);

        await cc.vv.gameData.awaitTime(0.5);

        let btn_collect = cc.find("btn_collect", parent);
        btn_collect.off("click");
        let func = async ()=>{
            btn_collect.off("click");
            Global.SlotsSoundMgr.playEffect("button");

            cc.tween(parent)
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .call(()=>{
                    this.result_node.active = false;
                    parent.active = false;
                    this._successCallback();
                    this._successCallback = null;
                })
                .start();
        }
        cc.vv.gameData.checkAutoPlay(btn_collect, func);
        btn_collect.on("click", async () => {
            btn_collect.stopAllActions();
            await func();
        });
    },

    async startPick(collectGame) {
        return new Promise((success)=>{
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("fgbgm");
            this.node.active = true;
            this.reset();
            this._successCallback = success;
            let miniGame = collectGame.roundInfo.miniGame;
            this.rubyCoin.string = Global.FormatNumToComma(miniGame.jackpotValues[3]);
            this.amethystCoin.string = Global.FormatNumToComma(miniGame.jackpotValues[2]);
            this.sapphireCoin.string = Global.FormatNumToComma(miniGame.jackpotValues[1]);
            this.emeraldCoin.string = Global.FormatNumToComma(miniGame.jackpotValues[0]);

            this._canSelect = true;


            for (let i = 1; i < 13; i++) {
                let item = cc.find("item_" + i, this.layout);
                let info = miniGame.items[i - 1];
                let spine = cc.find("spine", item).getComponent(sp.Skeleton);
                if (info.isOpen) {
                    this._haveOpenReward.push(i);
                    let animation = animationName[info.jackpotId - 1]
                    spine.setAnimation(0, animation + "_Loop_EN", true);
                } else {
                    spine.setAnimation(0, "Coin_Loop", true);
                }

            }
        });

    },

    getCollectGame() {
        return this._collectGame;
    },

    reset() {
        // 重置所有金币节点
        for (let i = 1; i < 13; i++) {
            let item = cc.find("item_" + i, this.layout);
            let spine = cc.find("spine", item).getComponent(sp.Skeleton);
            spine.setAnimation(0, "Coin_Loop", true);
        }

        // 重置结算界面
        this.result_node.active = false;

        // 重置变量
        this._successCallback = null;
        this._canSelect = false;
        this._haveOpenReward = [];
        this._winCoin = 0;
    },
});