/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        black_bg: cc.Node,
        wheel_node: cc.Node,
        wheel: cc.Node,
        spine_win: sp.Skeleton,
        btn_spin: cc.Node,
        result_node: cc.Node,

        _successCallback: null,
        _collectGame: null,
    },

    async startWheel(collectGame) {
        return new Promise((success) => {
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("fgbgm");
            this._successCallback = success;
            this.node.active = true;

            let cfg = collectGame.roundInfo.miniGame.items;
            for (let i = 1; i < cfg.length; i++) {
                let item = cfg[i];
                let node = cc.find("index_" + (i + 1), this.wheel);
                if (node) {
                    node.getComponent(cc.Label).string = Global.formatNumShort(item.coin, 0);
                }
            }

            this.wheel_node.active = true;
            this.wheel.rotation = 0;
            this.spine_win.node.active = false;

            this.btn_spin.off("click");
            let func = async ()=>{
                Global.SlotsSoundMgr.playEffect("WheelClick");
                this.btn_spin.off("click");
                let reqdata = {rtype: 4};
                let result = await cc.vv.gameData.reqSubGame(reqdata);
                if (result.code === 200) {
                    this._collectGame = result.data.collectGame;
                    Global.SlotsSoundMgr.playEffect("WheelSpin");
                    await this._rotateWheel(result.data.collectGame.roundInfo.miniGame.resultId - 1);
                    Global.SlotsSoundMgr.playEffect("WheelStop");
                    this.spine_win.node.active = true;

                    await cc.vv.gameData.awaitTime(2);

                    this.popResult(result.data.collectGame);
                }
            }
            cc.vv.gameData.checkAutoPlay(this.btn_spin, func);
            this.btn_spin.on("click", async () => {
                this.btn_spin.stopAllActions();
                await func();
            });
        })
    },

    getCollectGame() {
        return this._collectGame;
    },

    async popResult(collectGame) {
        Global.SlotsSoundMgr.playEffect("fgend");
        this.result_node.active = true;
        let parent = cc.find("parent", this.result_node);
        parent.active = true;
        parent.scale = 0;
        cc.tween(parent)
            .to(0.5, {scale: 1}, {easing: "backOut"})
            .start();

        cc.find("yifenkuang/coin", parent).getComponent(cc.Label).string = Global.FormatNumToComma(collectGame.roundInfo.miniGame.winCoin);

        await cc.vv.gameData.awaitTime(0.5);

        let btn_collect = cc.find("btn_collect", parent);
        btn_collect.off("click");
        let func = async ()=>{
            btn_collect.off("click");
            Global.SlotsSoundMgr.playEffect("button");

            cc.tween(parent)
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .call(() => {
                    this.result_node.active = false;
                    parent.active = false;
                    this._successCallback();
                    this._successCallback = null;
                })
                .start();
        }
        cc.vv.gameData.checkAutoPlay(btn_collect, func);
        btn_collect.on("click", async () => {
            btn_collect.stopAllActions();
            await func();
        });
    },

    async _rotateWheel(endIndex) {
        return new Promise((success) => {
            let angle = endIndex * 45 - 2160;
            cc.log(angle);

            let action = cc.rotateBy(6, angle).easing(cc.easeSineInOut());
            this.wheel.runAction(cc.sequence(action, cc.callFunc(() => {

                success();
            })));
        });
    },
});