/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {

    },

    OnReelSpinEnd:function(){
        this._reelState = []
        let slots = cc.find("bonus_slots", this.node.parent.parent.parent).getComponent("PoliticalStrategist_BonusSlots");
        slots.OnReelSpinEnd(this._reelIdx)

        //不能判断，停下来的列等于总共的列，因为有时候只旋转了3列
        //停下来的列以及等于最后一列旋转的列，
        //说明整个列已经停止
        let lastReelStopIdx = slots.GetLastStopReelIdx()
        if(this._reelIdx == lastReelStopIdx){
            //所有列都停止了
            slots.OnSpinEnd()
        }
    },

    playReelStop(){
        this._super();

        if (this._originResult) {
            for(let i = 0; i < this._originResult.length; i++){
                let item = this._symbols[i]
                if (item.GetShowId() === this._cfg.bonusId) {
                    Global.SlotsSoundMgr.playEffect("reelFW");
                    item.playStopAnimation();
                }
            }
        }
    },
});