/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        _endCallback: null,
        _wheels: [],
        _remainTimes: 0,
        _bonusGame: null,
        _winCoin: 0,
        _curWheel: null,
    },

    Init() {
        this._super();
        // this.node.active = false;
    },

    createReels: function (col, row) {
        for (let i = 0; i < col; i++) {
            let node = cc.find("reels/reel" + (i + 1), this.node)
            let scp = node.addComponent("PoliticalStrategist_BonusReel")
            scp.Init(i, row, this._topAniNode)
            this._reels.push(scp)
        }
    },

    async startBonusGame(bonusGame) {
        return new Promise(async (success) => {
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("bgbgm");
            this._bonusGame = bonusGame;
            this._endCallback = success;
            this.node.active = true;

            let firewheel_node = cc.find("firewheel_node", this.node);

            this.initAllSymbols();

            // TODO 稍后会改成按列排序
            for (let i = 0; i < bonusGame.items.length; i++) {
                let item = bonusGame.items[i];
                let symbol = this.GetSymbolByIdx(item.idx);

                let chengbeitishi = cc.instantiate(cc.find("ChengBeiTiShi", this.node));
                chengbeitishi.parent = symbol.node;
                chengbeitishi.active = true;
                Global.SlotsSoundMgr.playEffect("bgFWcollect");
                chengbeitishi.getComponent(sp.Skeleton).setAnimation(0, "HuoLun_FGDA_TiShi", false);
                chengbeitishi.getComponent(sp.Skeleton).setCompleteListener(() => {
                    chengbeitishi.getComponent(sp.Skeleton).setCompleteListener(null);
                    chengbeitishi.removeFromParent();
                    symbol.showNormalBonus();
                });

                let node = cc.instantiate(cc.vv.gameData.GetPrefabByName("symbol"));
                node.addComponent("PoliticalStrategist_Symbol");
                node.parent = cc.find("firewheel_layout", firewheel_node);
                let startPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                startPos = node.parent.convertToNodeSpaceAR(startPos);
                node.position = startPos;
                node.getComponent("PoliticalStrategist_Symbol").ShowById(this._cfg.bonusId, item);
                node.getComponent("PoliticalStrategist_Symbol").playidleAnimation();

                let endPos = cc.v2((0.5 + i) * 60, 0);
                this._wheels.push(node);

                cc.tween(node)
                    .to(0.5, {position: endPos, scale: 0.5})
                    .call(() => {
                        let cbts = cc.instantiate(cc.find("ChengBeiTiShi", this.node));
                        cbts.parent = node;
                        cbts.active = true;
                        cbts.getComponent(sp.Skeleton).setAnimation(0, "HuoLun_FGDA_TiShi", false);
                        cbts.getComponent(sp.Skeleton).setCompleteListener(() => {
                            cbts.getComponent(sp.Skeleton).setCompleteListener(null);
                            cbts.removeFromParent();
                        });

                        let times_cbts = cc.find("times/ChengBeiTiShi", firewheel_node);
                        times_cbts.active = true;
                        times_cbts.getComponent(sp.Skeleton).setAnimation(0, "HuoLun_FGNG _TiShi", false);
                        times_cbts.getComponent(sp.Skeleton).setCompleteListener(() => {
                            times_cbts.getComponent(sp.Skeleton).setCompleteListener(null);
                            times_cbts.active = false;
                        });

                        this._remainTimes++;
                        cc.find("times", firewheel_node).getComponent(cc.Label).string = this._remainTimes;
                    })
                    .start();

                await cc.vv.gameData.awaitTime(0.5);

            }

            await cc.vv.gameData.awaitTime(1);

            this.reqSpin();
        });
    },

    initAllSymbols() {
        let gameInfo = cc.vv.gameData.getGameInfo();
        if (gameInfo) {
            for (let i = 0; i < gameInfo.resultCards.length; i++) {
                let card = gameInfo.resultCards[i];
                let symbol = this.GetSymbolByIdx(i + 1);
                symbol.ShowById(card);
            }
            for (let item of this._bonusGame.items) {
                let symbol = this.GetSymbolByIdx(item.idx);
                symbol.ShowById(this._cfg.bonusId, item);
                symbol.playidleAnimation();
            }
        } else {
            for (let i = 0; i < 15; i++) {
                let symbol = this.GetSymbolByIdx(i + 1);
                symbol.ShowRandomSymbol();
            }
        }
    },

    //点击旋转按钮调用
    StartMove: function () {
        this._super();

        this._remainTimes--;
        cc.find("firewheel_node/times", this.node).getComponent(cc.Label).string = this._remainTimes;
    },

    async ReconnectShow() {
        let deskInfo = cc.vv.gameData.getDeskInfo();
        if (deskInfo.bonusGame) {
            this.node.active = true;
            cc.vv.gameData.setInBonusGame(true);
            let firewheel_node = cc.find("firewheel_node", this.node);
            for (let i = 0; i < deskInfo.bonusGame.items.length; i++) {
                let item = deskInfo.bonusGame.items[i];
                let node = cc.instantiate(cc.vv.gameData.GetPrefabByName("symbol"));
                node.parent = cc.find("firewheel_layout", firewheel_node);
                node.addComponent("PoliticalStrategist_Symbol");
                node.getComponent("PoliticalStrategist_Symbol").ShowById(this._cfg.bonusId, item);
                node.getComponent("PoliticalStrategist_Symbol").playidleAnimation();
                node.scale = 0.5;
                let endPos = cc.v2((0.5 + i) * 60, 0);
                node.position = endPos;
                this._wheels.push(node);
            }
            this._remainTimes = deskInfo.bonusGame.items.length;
            cc.find("times", firewheel_node).getComponent(cc.Label).string = this._remainTimes;

            await cc.vv.gameData.awaitTime(0.5);
            cc.find("slots", this.node.parent).active = false;
            this.reqSpin();
        } else {
            this.node.active = false;
        }
    },

    async reqSpin() {
        // this._remainTimes--;
        // if (this._remainTimes < 0) {
        //     this._remainTimes = 0;
        // }
        // cc.find("firewheel_node/times", this.node).getComponent(cc.Label).string = this._remainTimes;

        this.StartMove();

        let node = this._wheels[0];
        let newWheel = cc.instantiate(cc.vv.gameData.GetPrefabByName("symbol"));
        newWheel.parent = this.node;
        newWheel.addComponent("PoliticalStrategist_Symbol");
        newWheel.getComponent("PoliticalStrategist_Symbol")
            .ShowById(this._cfg.bonusId, node.getComponent("PoliticalStrategist_Symbol").GetData());
        newWheel.getComponent("PoliticalStrategist_Symbol").playidleAnimation();
        let startPos = node.convertToWorldSpaceAR(cc.v2(0, 0));
        startPos = this.node.convertToNodeSpaceAR(startPos);
        newWheel.position = startPos;
        this._curWheel = newWheel;
        node.active = false;

        let endPos = cc.find("firewheel_node/middle_node", this.node).convertToWorldSpaceAR(cc.v2(0, 0));
        endPos = this.node.convertToNodeSpaceAR(endPos);
        cc.log(endPos);
        Global.SlotsSoundMgr.playEffect("bgFWfly");
        cc.tween(newWheel)
            .to(0.5, {position: endPos, scale: 2})
            .start();

        for (let i = 1; i < this._wheels.length; i++) {
            let wheel = this._wheels[i];
            cc.tween(wheel)
                .by(0.5, {x: -60})
                .start();
        }

        await cc.vv.gameData.awaitTime(1);
        let reqdata = {rtype: 1};
        let result = await cc.vv.gameData.reqSubGame(reqdata);
        if (result.code === 200 && !result.spcode) {
            this.onMsgSpine(result.data);


        }
    },

    async onMsgSpine(msg) {
        this._gameInfo = msg.result
        this._bonusGame = msg.bonusGame;
        let cards = msg.result.resultCards
        this.SetSlotsResult(cards);
    },

    SetSlotsResult: function (cards) {
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []
        for (let i = 0; i < cards.length; i++) {
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if (this._cfg.symbol[cards[i]]) {
                let res = {}
                res.sid = cards[i] //符号id
                if (cards[i] === this._cfg.bonusId) {
                    for (let item of this._gameInfo.newItems) {
                        if (item.idx === (i + 1)) {
                            res.data = item;
                            break;
                        }
                    }
                }
                if (!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }
        }

        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    //显示中奖路线
    //竞品中的显示线路是：先总，后单条循环。目前我们只显示总的
    ShowWinTrace: function () {
        this._super();
    },

    //重写：显示bonus中奖
    async OnSpinEnd() {
        // 如果是倍数先判断是否赢钱，赢钱了中间的风火轮要播动画，然后播放中线，然后播放卷轴中如果再中了风火轮的动画
        if (this._gameInfo.winCoin > 0 && this._gameInfo.item.mult > 1) {
            await new Promise((success) => {
                Global.SlotsSoundMgr.playEffect("bgFWmult");
                let node = this._wheels[0];
                cc.tween(node)
                    .to(0.2, {scale: 2.1})
                    .to(0.2, {scale: 2})
                    .delay(0.5)
                    .call(() => {
                        success();
                    })
                    .start();

                let chengbeitishi = cc.instantiate(cc.find("ChengBeiTiShi", this.node));
                chengbeitishi.parent = node;
                chengbeitishi.active = true;
                chengbeitishi.getComponent(sp.Skeleton).setAnimation(0, "HuoLun_FGDA_TiShi", false);
                chengbeitishi.getComponent(sp.Skeleton).setCompleteListener(() => {
                    chengbeitishi.removeFromParent();
                });
            });
        }

        this.ShowWinTrace();

        let winCoin = this._gameInfo.lineWinCoin * this._gameInfo.item.mult;
        let totalWinCoin = this._bonusGame.winCoin - this._gameInfo.winCoin + winCoin;

        this.ShowBottomWin(winCoin, totalWinCoin, true, async () => {
            await this.triggerFireWheel();

            if (this._bonusGame.isEnd) {
                // 结束了
                await this.popBonusResultDialog();

                if (this._endCallback) {
                    this._endCallback();
                    this._endCallback = null;
                } else {
                    let slots = cc.vv.gameData.GetSlotsScript();
                    slots.cutSceneFire();
                    await cc.vv.gameData.awaitTime(1);
                    cc.vv.gameData.setInBonusGame(false);
                    slots.node.active = true;
                    this.node.active = false;
                    slots.ShowBottomWin(this._bonusGame.winCoin, this._bonusGame.winCoin, true, ()=>{
                        slots.CanDoNextRound();
                    });
                }
            }
        });
    },

    async triggerFireWheel() {
        if (this._gameInfo.newItems.length > 0) {
            for (let item of this._gameInfo.newItems) {
                await new Promise((success) => {
                    let symbol = this.GetSymbolByIdx(item.idx);
                    Global.SlotsSoundMgr.playEffect("bgFWcollect");
                    cc.tween(symbol.node)
                        .to(0.2, {scale: 1.1})
                        .to(0.2, {scale: 1})
                        .call(() => {
                            symbol.showNormalBonus();
                            let node = cc.instantiate(cc.vv.gameData.GetPrefabByName("symbol"));
                            node.addComponent("PoliticalStrategist_Symbol");
                            node.parent = cc.find("firewheel_node/firewheel_layout", this.node);
                            node.position = cc.v2((0.5 + this._wheels.length - 1) * 60, 0);
                            node.scale = 0;
                            node.getComponent("PoliticalStrategist_Symbol").ShowById(this._cfg.bonusId, item);
                            node.getComponent("PoliticalStrategist_Symbol").playidleAnimation();
                            cc.tween(node)
                                .to(0.2, {scale: 0.5})
                                .start();
                            this._wheels.push(node);

                            let times_cbts = cc.find("firewheel_node/times/ChengBeiTiShi", this.node);
                            times_cbts.active = true;
                            times_cbts.getComponent(sp.Skeleton).setAnimation(0, "HuoLun_FGNG_TiShi", false);
                            times_cbts.getComponent(sp.Skeleton).setCompleteListener(() => {
                                times_cbts.getComponent(sp.Skeleton).setCompleteListener(null);
                                times_cbts.active = false;
                            });

                            this._remainTimes++;
                            cc.find("firewheel_node/times", this.node).getComponent(cc.Label).string = this._remainTimes;

                            let chengbeitishi = cc.instantiate(cc.find("ChengBeiTiShi", this.node));
                            chengbeitishi.parent = node;
                            chengbeitishi.active = true;
                            chengbeitishi.getComponent(sp.Skeleton).setAnimation(0, "HuoLun_FGDA_TiShi", false);
                            chengbeitishi.getComponent(sp.Skeleton).setCompleteListener(() => {
                                chengbeitishi.removeFromParent();
                                success();
                            });
                        })
                        .start();

                    let chengbeitishi = cc.instantiate(cc.find("ChengBeiTiShi", this.node));
                    chengbeitishi.parent = symbol.node;
                    chengbeitishi.active = true;
                    chengbeitishi.getComponent(sp.Skeleton).setAnimation(0, "HuoLun_FGDA_TiShi", false);
                    chengbeitishi.getComponent(sp.Skeleton).setCompleteListener(() => {
                        chengbeitishi.removeFromParent();
                    });
                });
            }

            await cc.vv.gameData.awaitTime(0.5);
        }

        if (this._gameInfo.item.isJackpot) {
            cc.find("black_bg", this.node).active = true;
            let wheel = this._wheels[0];
            Global.SlotsSoundMgr.playEffect("bgJPdown");
            let position = cc.find("black_bg", this.node).convertToWorldSpaceAR(cc.v2(0, 0));
            position = this.node.convertToNodeSpaceAR(position);
            cc.tween(this._curWheel)
                .to(0.5, {scale: 2, position: position})
                .start();

            await cc.vv.gameData.awaitTime(1);
            let spine = this._curWheel.getComponent("PoliticalStrategist_Symbol").getBonusSpine();
            let animations = ["Mini", "Minor", "Major", "Grand"];

            if (this._gameInfo.item.jackpot) {
                let prizePool = cc.find("LMSlots_PrizePool_1/prizePool_" + animations[this._gameInfo.item.jackpot.id - 1], this.node.parent);
                if (this._gameInfo.item.jackpot.value) {
                    Global.SlotsSoundMgr.playEffect("JPchangeFast");
                    spine.setAnimation(0, "HuoLun_" + animations[this._gameInfo.item.jackpot.id - 1] + "_Intro2", false);
                    spine.addAnimation(0, "HuoLun_" + animations[this._gameInfo.item.jackpot.id - 1] + "_Loop1", true);

                    await cc.vv.gameData.awaitTime(3);
                    spine.setAnimation(0, "HuoLun_" + animations[this._gameInfo.item.jackpot.id - 1] + "_Loop2", true);

                    let endPos = null;
                    if (this._gameInfo.item.jackpot.id > 2) {
                        endPos = cc.find("reward_3", prizePool).convertToWorldSpaceAR(cc.v2(0, 0));
                    } else {
                        endPos = cc.find("reward_1", prizePool).convertToWorldSpaceAR(cc.v2(0, 0));
                    }
                    cc.find("black_bg", this.node).active = false;
                    endPos = this.node.convertToNodeSpaceAR(endPos);

                    Global.SlotsSoundMgr.playEffect("JPcollect");
                    cc.tween(this._curWheel)
                        .to(0.5, {position: endPos, scale: 0.5})
                        .call(() => {
                            this._wheels.shift();
                        })
                        .removeSelf()
                        .start();


                    cc.find("reward_1/HuoLun", prizePool).active = true;
                    cc.find("jp_kuang", prizePool).active = true;

                    await cc.vv.gameData.awaitTime(1.5);

                    await this.popJackpotDialog();
                } else {
                    Global.SlotsSoundMgr.playEffect("JPchange");
                    // 没有直接中jackpot
                    spine.setAnimation(0, "HuoLun_" + animations[this._gameInfo.item.jackpot.id - 1] + "_Intro1", false);
                    spine.addAnimation(0, "HuoLun_" + animations[this._gameInfo.item.jackpot.id - 1] + "_Loop1", true);

                    await cc.vv.gameData.awaitTime(3);
                    cc.find("black_bg", this.node).active = false;
                    spine.setAnimation(0, "HuoLun_" + animations[this._gameInfo.item.jackpot.id - 1] + "_Loop2", true);
                    let count = this._gameInfo.item.jackpot.id === 3 ? this._bonusGame.majorCnt : this._bonusGame.grandCnt;
                    let endPos = cc.find("reward_" + count, prizePool).convertToWorldSpaceAR(cc.v2(0, 0));
                    endPos = this.node.convertToNodeSpaceAR(endPos);
                    Global.SlotsSoundMgr.playEffect("JPcollect");
                    cc.tween(this._curWheel)
                        .to(0.5, {position: endPos, scale: 0.5})
                        .call(() => {
                            cc.find("reward_" + count + "/HuoLun", prizePool).active = true;
                            this._wheels.shift();
                        })
                        .removeSelf()
                        .start();

                    await cc.vv.gameData.awaitTime(1.5);

                }
            } else {
                // jackpot变成钱
                this._curWheel.getComponent("PoliticalStrategist_Symbol").showWheelCoin(this._gameInfo.item.coin);

                await cc.vv.gameData.awaitTime(3);
                cc.find("black_bg", this.node).active = false;
                this._wheels.shift();
                cc.tween(this._curWheel)
                    .to(0.3, {opacity: 0})
                    .removeSelf()
                    .start();

                await cc.vv.gameData.awaitTime(0.5);

                await new Promise((success)=>{
                    this.ShowBottomWin(this._gameInfo.winCoin - this._gameInfo.lineWinCoin, this._bonusGame.winCoin, false, ()=>{
                        success();
                    });
                });
            }
        } else {

            this._wheels.shift();
            cc.tween(this._curWheel)
                .to(0.3, {opacity: 0})
                .removeSelf()
                .start();
            await cc.vv.gameData.awaitTime(0.5);
        }

        await cc.vv.gameData.awaitTime(0.5);

        if (!this._bonusGame.isEnd) {
            this.reqSpin();
        }
    },

    async popJackpotDialog() {
        return new Promise(async (success) => {
            Global.SlotsSoundMgr.playEffect("JPwin");

            let free_dialog = cc.find("free_dialog", this.node.parent);
            free_dialog.active = true;

            let dialog = cc.find("jackpot_node", free_dialog);
            dialog.active = true;
            dialog.scale = 1;

            let animations = ["Mini", "Minor", "Major", "Grand"];
            let jackpot = cc.find(animations[this._gameInfo.item.jackpot.id - 1], dialog);
            jackpot.active = true;
            jackpot.scale = 0;
            cc.tween(jackpot)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();
            let sounds = ["mini", "minor", "major", "grand"];
            Global.SlotsSoundMgr.playEffect("VO_" + sounds[this._gameInfo.item.jackpot.id - 1] + "_jackpot_EN");

            let yifenkuang = cc.find("yifenkuang", dialog);
            yifenkuang.scale = 0;
            cc.tween(yifenkuang)
                .delay(0.1)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();
            cc.find("coin", yifenkuang).getComponent(cc.Label).string =
                Global.FormatNumToComma(this._gameInfo.jackpotValues[this._gameInfo.item.jackpot.id - 1]);

            let btn_collect = cc.find("btn_collect", dialog);
            btn_collect.scale = 0;
            cc.tween(btn_collect)
                .delay(0.2)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            await cc.vv.gameData.awaitTime(1);

            let prizePool = cc.find("LMSlots_PrizePool_1/prizePool_" + animations[this._gameInfo.item.jackpot.id - 1], this.node.parent);
            btn_collect.off("click");
            let func = async ()=>{
                btn_collect.off("click");
                Global.SlotsSoundMgr.playEffect("button");

                cc.tween(dialog)
                    .to(0.5, {scale: 0}, {easing: "backIn"})
                    .call(() => {
                        for (let i = 1; i < 4; i++) {
                            let reward = cc.find("reward_" + i, prizePool);
                            if (reward) {
                                cc.find("HuoLun", reward).active = false;
                            }
                        }
                        cc.find("jp_kuang", prizePool).active = false;
                        free_dialog.active = false;
                        dialog.active = false;
                        jackpot.active = false;
                        let winCoin = this._gameInfo.jackpotValues[this._gameInfo.item.jackpot.id - 1];
                        let totalWinCoin = this._bonusGame.winCoin;
                        this.ShowBottomWin(winCoin, totalWinCoin, false, ()=>{
                            success();
                        });
                    })
                    .start();
            }
            cc.vv.gameData.checkAutoPlay(btn_collect, func);
            btn_collect.on("click", async () => {
                btn_collect.stopAllActions();
                await func();
            });
        })
    },

    popBonusResultDialog() {
        return new Promise(async (success) => {
            Global.SlotsSoundMgr.playEffect("bgend");

            let free_dialog = cc.find("free_dialog", this.node.parent);
            free_dialog.active = true;

            let dialog = cc.find("bonus_result_node", free_dialog);
            dialog.active = true;
            dialog.scale = 1;

            let freetanchuang = cc.find("freetanchuang", dialog);
            freetanchuang.scale = 0;
            cc.tween(freetanchuang)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            let total_won_EN = cc.find("total_won_EN", dialog);
            total_won_EN.scale = 0;
            cc.tween(total_won_EN)
                .delay(0.1)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            let yifenkuang = cc.find("yifenkuang", dialog);
            yifenkuang.scale = 0;
            cc.tween(yifenkuang)
                .delay(0.2)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();
            this._winCoin = this._bonusGame.winCoin;
            cc.find("coin", yifenkuang).getComponent(cc.Label).string =
                Global.FormatNumToComma(this._bonusGame.winCoin);

            let btn_collect = cc.find("btn_collect", dialog);
            btn_collect.scale = 0;
            cc.tween(btn_collect)
                .delay(0.3)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            await cc.vv.gameData.awaitTime(1);

            btn_collect.off("click");

            let func = async ()=>{
                btn_collect.off("click");
                Global.SlotsSoundMgr.playEffect("button");

                cc.tween(dialog)
                    .to(0.5, {scale: 0}, {easing: "backIn"})
                    .call(() => {
                        let animations = ["Mini", "Minor", "Major", "Grand"];
                        for (let i = 0; i < animations.length; i++) {
                            let prizePool = cc.find("LMSlots_PrizePool_1/prizePool_" + animations[i], this.node.parent);
                            for (let j = 1; j < 4; j++) {
                                let reward = cc.find("reward_" + j, prizePool);
                                if (reward) {
                                    cc.find("HuoLun", reward).active = false;
                                }
                            }
                        }

                        free_dialog.active = false;
                        dialog.active = false;
                        success();
                    })
                    .start();
            }
            cc.vv.gameData.checkAutoPlay(btn_collect, func);
            btn_collect.on("click", async () => {
                btn_collect.stopAllActions();
                await func();
            });
        })
    },

    getWinCoin() {
        return this._winCoin;
    }
});