﻿/**
 * @description
 */

let CollectGameItemType = {
    Coin: 0,  // 金币
    Mystery: 1,  // 宝箱
    Pearl: 2,  // 珍珠
    GoldenKoi: 3,  // 金色锦鲤
    DragonBlade: 4,  // 龙叉
    PrizeBooster: 5,  // 奖金增强
    DragonKing: 6,  // 龙王
};

cc.Class({
    extends: cc.Component,
    properties: {
        mapLevel: cc.Sprite,
        levelPrize: cc.Label,
        mapStar: cc.Node,
        starPercent: cc.Label,
        btnClose: cc.Node,
        basePrize: cc.Label,
        totalWin: cc.Label,
        boxMulti: cc.Label,
        pearlMulti: cc.Label,
        fishMulti: cc.Label,
        sanchajiMulti: cc.Label,
        prizeBoosterMulti: cc.Label,
        jianglibian: sp.Skeleton,
        detail: cc.Node,
        points: [cc.Node],
        role: cc.Node,
        role_spine: sp.Skeleton,
        arrow_up: cc.Node,
        touch_up: cc.Node,
        arrow_down: cc.Node,
        touch_down: cc.Node,
        arrow_left: cc.Node,
        touch_left: cc.Node,
        arrow_right: cc.Node,
        touch_right: cc.Node,
        role_prizeBooster: sp.Skeleton,
        role_pearl: sp.Skeleton,
        role_pearlMulti: cc.Node,
        role_box: sp.Skeleton,
        role_sanchaji: sp.Skeleton,
        role_fish: sp.Skeleton,
        role_coin: cc.Label,
        wheel: cc.Node,
        pickGame: cc.Node,

        // 中了box
        boxSelect: cc.Node,
        boxSelectBlackBg: cc.Node,
        boxLevelPrize: cc.Node,
        boxLevelPrizeCoin: cc.Label,
        boxMysteryPrize: cc.Node,
        boxMysteryPrizeMinCoin: cc.Label,
        boxMysteryPrizeMaxCoin: cc.Label,
        boxMysteryPrizeCoin: cc.Label,
        boxSelectChooseBoard: cc.Node,

        // 结算
        resultNode: cc.Node,
        resultBoxEnd: cc.Node,
        resultPearlEnd: cc.Node,
        resultSanchajiEnd: cc.Node,
        resultWinCoin: cc.Label,
        btnCollect: cc.Node,

        // 弹窗
        dialogNode: cc.Node,


        _endCallback: null,
        _curIndex: 0,   // 当前位置
        _collectGame: null,
        _finalWinCoin: 0,

        _canGo: true,
    },

    openMap(collectGame) {
        this.node.active = true;
        this._collectGame = collectGame;

        this.mapLevel.node.getComponent("ImgSwitchCmp").setIndex(collectGame.level - 1);
        this.levelPrize.string = Global.FormatNumToComma(collectGame.levelPrizeMult * (1 + collectGame.boosterPercent / 100) * collectGame.startPrize);
        this.boxMulti.string = "X" + collectGame.itemCnt[0];
        this.pearlMulti.string = "X" + collectGame.itemCnt[1];
        this.fishMulti.string = "X" + collectGame.itemCnt[2];
        this.sanchajiMulti.string = "X" + collectGame.itemCnt[3];
        this.prizeBoosterMulti.string = "X" + collectGame.itemCnt[4];
        this.basePrize.string = Global.FormatNumToComma(collectGame.startPrize);
        this.totalWin.string = Global.FormatNumToComma(0);

        // 地图信息开始
        this._curIndex = collectGame.currIdx;
        let curPos = cc.find("point_" + collectGame.currIdx, this.detail).convertToWorldSpaceAR(cc.v2(0, 0));
        curPos = this.detail.parent.convertToNodeSpaceAR(curPos);
        this.role.position = curPos;
        this.resetRole();
        this.hideArrow();

        for (let i = 0; i < collectGame.boardInfo.length; i++) {
            let info = collectGame.boardInfo[i];
            // let point = cc.find("point_" + (i + 1), this.detail);
            this.showInfo(i + 1, info);
        }

        this.btnClose.active = true;
        this.btnClose.off("click");
        this.btnClose.on("click", ()=>{
            this.btnClose.off("click");
            Global.SlotsSoundMgr.playEffect("mapInOut");
            this.node.active = false;
        });
    },

    startMapGame(collectGame) {
        return new Promise(async (success)=>{
            this.btnClose.active = false;
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("mapbgm");
            this.node.active = true;
            this._endCallback = success;
            this._collectGame = collectGame;

            this.mapLevel.node.getComponent("ImgSwitchCmp").setIndex(collectGame.level - 1);
            this.levelPrize.string = Global.FormatNumToComma(collectGame.levelPrizeMult * (1 + collectGame.boosterPercent / 100) * collectGame.startPrize);
            this.boxMulti.string = "X" + collectGame.itemCnt[0];
            this.pearlMulti.string = "X" + collectGame.itemCnt[1];
            this.fishMulti.string = "X" + collectGame.itemCnt[2];
            this.sanchajiMulti.string = "X" + collectGame.itemCnt[3];
            this.prizeBoosterMulti.string = "X" + collectGame.itemCnt[4];
            this.basePrize.string = Global.FormatNumToComma(collectGame.startPrize);
            this.totalWin.string = Global.FormatNumToComma(collectGame.roundInfo.winCoin);

            // 地图信息开始
            this._curIndex = collectGame.currIdx;
            let curPos = cc.find("point_" + collectGame.currIdx, this.detail).convertToWorldSpaceAR(cc.v2(0, 0));
            curPos = this.detail.parent.convertToNodeSpaceAR(curPos);
            this.role.position = curPos;
            this.resetRole();
            if (collectGame.state === 1) {
                this.showArrow(collectGame.currIdx);
            } else {
                this.hideArrow();
            }

            for (let i = 0; i < collectGame.boardInfo.length; i++) {
                let info = collectGame.boardInfo[i];
                // let point = cc.find("point_" + (i + 1), this.detail);
                this.showInfo(i + 1, info);
            }

            this.touch_up.off(cc.Node.EventType.TOUCH_END);
            this.touch_up.on(cc.Node.EventType.TOUCH_END, ()=>{
                if (!this._canGo) {
                    return;
                }
                if (!this.arrow_up.active) {
                    return;
                }
                this.go(1);
            });

            this.touch_down.off(cc.Node.EventType.TOUCH_END);
            this.touch_down.on(cc.Node.EventType.TOUCH_END, ()=>{
                if (!this._canGo) {
                    return;
                }
                if (!this.arrow_down.active) {
                    return;
                }
                this.go(2);
            });

            this.touch_left.off(cc.Node.EventType.TOUCH_END);
            this.touch_left.on(cc.Node.EventType.TOUCH_END, ()=>{
                if (!this._canGo) {
                    return;
                }
                if (!this.arrow_left.active) {
                    return;
                }
                this.go(3);
            });

            this.touch_right.off(cc.Node.EventType.TOUCH_END);
            this.touch_right.on(cc.Node.EventType.TOUCH_END, ()=>{
                if (!this._canGo) {
                    return;
                }
                if (!this.arrow_right.active) {
                    return;
                }
                this.go(4);
            });
            
            if (collectGame.state === 2) {
                let curInfo = collectGame.boardInfo[collectGame.currIdx - 1];
                if (curInfo.type === CollectGameItemType.GoldenKoi) {
                    let pickgameScript = this.pickGame.getComponent("PoliticalStrategist_PickGame");
                    this.pickGame.active = true;
                    await pickgameScript.startPick(this._collectGame);
                    this._collectGame = pickgameScript.getCollectGame();

                    await cc.vv.gameData.awaitTime(0.5);

                    this.cutSceneFish(false);

                    await cc.vv.gameData.awaitTime(1.5);

                    this.pickGame.active = false;

                    await cc.vv.gameData.awaitTime(1);

                    this.popResult(3);
                } else if (curInfo.type === CollectGameItemType.DragonBlade) {
                    let wheelScript = this.wheel.getComponent("PoliticalStrategist_Wheel");
                    this.wheel.active = true;
                    await wheelScript.startWheel(this._collectGame);
                    this._collectGame = wheelScript.getCollectGame();

                    await cc.vv.gameData.awaitTime(0.5);

                    this.cutSceneSanchaji(false);

                    await cc.vv.gameData.awaitTime(1.5);

                    this.wheel.active = false;

                    await cc.vv.gameData.awaitTime(1);

                    this.popResult(3);
                }
            } else if (collectGame.state === 3) {
                this.chooseBox();
            }
        });
    },

    /**
     * 1上2下3左4右
     * @param direction
     */
    async go(direction) {
        Global.SlotsSoundMgr.playEffect("mapPointer");
        this.hideArrow();
        let nextIndex = this._curIndex;
        switch (direction) {
            case 1:
                nextIndex = this._curIndex - 6;
                this.role_spine.node.scaleX = 1;
                break;
            case 2:
                nextIndex = this._curIndex + 6;
                this.role_spine.node.scaleX = 1;
                break;
            case 3:
                nextIndex = this._curIndex - 1;
                this.role_spine.node.scaleX = 1;
                break;
            case 4:
                nextIndex = this._curIndex + 1;
                this.role_spine.node.scaleX = -1;
                break;
        }
        let nextInfo = this._collectGame.boardInfo[nextIndex - 1];
        if (nextInfo.isOpen) {
            // 已经打开的就直接走，不需要给服务器发消息
            this.showInfo(this._curIndex, this._collectGame.boardInfo[this._curIndex - 1]);
            this.resetRole();
            this._curIndex = nextIndex;
            let point = cc.find("point_" + this._curIndex, this.detail);
            let pos = point.convertToWorldSpaceAR(cc.v2(0, 0));
            pos = this.detail.parent.convertToNodeSpaceAR(pos);
            Global.SlotsSoundMgr.playEffect("NezhaMove");
            cc.tween(this.role)
                .to(0.5, {position: pos})
                .start();
            await cc.vv.gameData.awaitTime(1);
            this.showArrow(this._curIndex);
            return;
        }
        let reqdata = {rtype:2, choiceId: nextIndex};
        let result = await cc.vv.gameData.reqSubGame(reqdata);
        if(result.code === 200){
            this.showInfo(this._curIndex, this._collectGame.boardInfo[this._curIndex - 1]);
            let collectGame = result.data.collectGame;
            cc.vv.gameData.getDeskInfo().collectGame = result.data.collectGame;
            this._collectGame = collectGame;
            this._curIndex = collectGame.currIdx;
            let point = cc.find("point_" + this._curIndex, this.detail);
            cc.find("bg", point).active = false;
            Global.SlotsSoundMgr.playEffect("mapCrack");
            let shuikuai = cc.find("map_shuikuai", point).getComponent(sp.Skeleton);
            shuikuai.node.active = true;
            shuikuai.setAnimation(0, "shui4", false);
            shuikuai.setCompleteListener(()=>{
                shuikuai.setCompleteListener(null);
                shuikuai.node.active = false;
            });

            this.resetRole();
            let pos = point.convertToWorldSpaceAR(cc.v2(0, 0));
            pos = this.detail.parent.convertToNodeSpaceAR(pos);
            Global.SlotsSoundMgr.playEffect("NezhaMove");
            cc.tween(this.role)
                .to(0.5, {position: pos})
                .start();

            await cc.vv.gameData.awaitTime(1);

            let info = collectGame.boardInfo[this._curIndex - 1];
            if (info.type === CollectGameItemType.Coin) {
                Global.SlotsSoundMgr.playEffect("mapCredit");
                this.role_coin.node.active = true;
                this.role_coin.string = Global.formatNumShort(info.coin, 0);
                this.role_coin.node.scale = 0;
                cc.tween(this.role_coin.node)
                    .to(0.5, {scale: 1}, {easing: "backOut"})
                    .call(()=>{
                        Global.doRoallNumEff(this.totalWin.node, collectGame.roundInfo.baseCoin - info.coin,
                            collectGame.roundInfo.baseCoin, 1.5, null, null, 0, true);
                    })
                    .start();

                await cc.vv.gameData.awaitTime(2);
                this.showArrow(this._curIndex);
            } else if (info.type === CollectGameItemType.Mystery) {
                Global.SlotsSoundMgr.playEffect("mapCredit");
                this.role_box.node.active = true;
                this.role_box.setAnimation(0, "box_intro", false);
                this.role_box.setCompleteListener(()=>{
                    this.role_box.setCompleteListener(null);
                    Global.SlotsSoundMgr.playEffect("mapChestShake");
                    this.role_box.setAnimation(0, "box_open", false);
                    let endPosition = this.node.convertToWorldSpaceAR(cc.v2(0, 0));
                    endPosition = this.role.convertToNodeSpaceAR(endPosition);
                    cc.tween(this.role_box.node)
                        .to(0.5, {position: endPosition})
                        .start();
                    this.role_box.setCompleteListener(()=>{
                        this.role_box.setCompleteListener(null);
                        this.role_box.node.position = cc.v2(0, 0);
                        this.role_box.node.active = false;
                        this.chooseBox();
                    });
                })
            } else if (info.type === CollectGameItemType.PrizeBooster) {
                Global.SlotsSoundMgr.playEffect("mapCredit");
                this.role_prizeBooster.node.active = true;
                this.role_prizeBooster.setAnimation(0, "Prizebooster", false);
                this.role_prizeBooster.setCompleteListener(async ()=>{
                    this.role_prizeBooster.setCompleteListener(null);

                    this.jianglibian.node.active = true;
                    let pos = this.prizeBoosterMulti.node.parent.convertToWorldSpaceAR(cc.v2(0, 0));
                    pos = this.node.convertToNodeSpaceAR(pos);
                    this.jianglibian.node.position = pos;
                    this.jianglibian.setAnimation(0, "Map_jiangliban", false);
                    this.jianglibian.setCompleteListener(()=>{
                        this.jianglibian.setCompleteListener(null);
                        this.jianglibian.node.active = false;
                        this.prizeBoosterMulti.string = "X" + this._collectGame.itemCnt[4];
                    });

                    Global.SlotsSoundMgr.playEffect("mapAdded");
                    let particle = cc.instantiate(cc.find("particle_fly", this.node.parent));
                    particle.active = true;
                    let startPos = this.role_prizeBooster.node.convertToWorldSpaceAR(cc.v2(0, 0));
                    startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                    let endPos = this.mapStar.convertToWorldSpaceAR(cc.v2(0, 0));
                    endPos = this.node.parent.convertToNodeSpaceAR(endPos);
                    particle.parent = this.node.parent;
                    particle.position = startPos;
                    cc.tween(particle)
                        .to(0.5, {position: endPos})
                        .call(()=>{
                            this.starPercent.string = this._collectGame.boosterPercent + "%";
                        })
                        .removeSelf()
                        .start();

                    await cc.vv.gameData.awaitTime(1);

                    this.showArrow(this._curIndex);
                });
            } else if (info.type === CollectGameItemType.Pearl) {
                Global.SlotsSoundMgr.playEffect("mapCredit");
                this.role_pearl.node.active = true;
                this.role_pearlMulti.active = false;
                this.role_pearl.setAnimation(0, "map_beike_inro", false);

                await cc.vv.gameData.awaitTime(1);
                this.role_pearl.setAnimation(0, "map_beike_open", false);
                let index = 0;
                switch (this._collectGame.roundInfo.mult) {
                    case 2:
                        index = 0;
                        break;
                    case 3:
                        index = 1;
                        break;
                    case 5:
                        index = 2;
                        break;
                    case 10:
                        index = 3;
                        break;
                    case 25:
                        index = 4;
                        break;
                }
                this.role_pearlMulti.getComponent("ImgSwitchCmp").setIndex(index);
                this.role_pearl.setCompleteListener(async ()=>{
                    this.role_pearl.setCompleteListener(null);

                    this.jianglibian.node.active = true;
                    let pos = this.pearlMulti.node.parent.convertToWorldSpaceAR(cc.v2(0, 0));
                    pos = this.node.convertToNodeSpaceAR(pos);
                    this.jianglibian.node.position = pos;
                    this.jianglibian.setAnimation(0, "Map_jiangliban", false);
                    this.jianglibian.setCompleteListener(()=>{
                        this.jianglibian.setCompleteListener(null);
                        this.jianglibian.node.active = false;
                        this.pearlMulti.string = "X" + this._collectGame.itemCnt[1];
                    });

                    Global.SlotsSoundMgr.playEffect("mapAdded");
                    let particle = cc.instantiate(cc.find("particle_fly", this.node.parent));
                    particle.active = true;
                    let startPos = this.role_pearl.node.convertToWorldSpaceAR(cc.v2(0, 0));
                    startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                    let endPos = this.totalWin.node.convertToWorldSpaceAR(cc.v2(0, 0));
                    endPos = this.node.parent.convertToNodeSpaceAR(endPos);
                    particle.parent = this.node.parent;
                    particle.position = startPos;
                    cc.tween(particle)
                        .to(0.5, {position: endPos})
                        .call(()=>{
                            this.totalWin.string = Global.FormatNumToComma(this._collectGame.roundInfo.winCoin);
                        })
                        .removeSelf()
                        .start();

                    await cc.vv.gameData.awaitTime(1);

                    this.popResult(2);
                });
            } else if (info.type === CollectGameItemType.DragonBlade) {
                Global.SlotsSoundMgr.playEffect("mapCredit");
                this.role_sanchaji.node.active = true;
                this.role_sanchaji.setAnimation(0, "sanchaji_intro", false);
                this.role_sanchaji.setCompleteListener(async ()=>{
                    this.role_sanchaji.setCompleteListener(null);

                    this.jianglibian.node.active = true;
                    let pos = this.sanchajiMulti.node.parent.convertToWorldSpaceAR(cc.v2(0, 0));
                    pos = this.node.convertToNodeSpaceAR(pos);
                    this.jianglibian.node.position = pos;
                    this.jianglibian.setAnimation(0, "Map_jiangliban", false);
                    this.jianglibian.setCompleteListener(()=>{
                        this.jianglibian.setCompleteListener(null);
                        this.jianglibian.node.active = false;
                        this.sanchajiMulti.string = "X" + this._collectGame.itemCnt[3];
                    });
                });

                await cc.vv.gameData.awaitTime(2);

                await this.popDialog(1);

                this.cutSceneSanchaji(true);

                await cc.vv.gameData.awaitTime(1.5);

                let wheelScript = this.wheel.getComponent("PoliticalStrategist_Wheel");
                this.wheel.active = true;
                await wheelScript.startWheel(this._collectGame);
                this._collectGame = wheelScript.getCollectGame();

                await cc.vv.gameData.awaitTime(0.5);

                this.cutSceneSanchaji(false);

                await cc.vv.gameData.awaitTime(1.5);

                this.wheel.active = false;

                await cc.vv.gameData.awaitTime(1);

                this.popResult(3);
            } else if (info.type === CollectGameItemType.GoldenKoi) {
                Global.SlotsSoundMgr.playEffect("mapCredit");
                this.role_fish.node.active = true;
                this.role_fish.setAnimation(0, "liyu_intro", false);
                this.role_fish.setCompleteListener(async ()=>{
                    this.role_fish.setCompleteListener(null);

                    this.jianglibian.node.active = true;
                    let pos = this.fishMulti.node.parent.convertToWorldSpaceAR(cc.v2(0, 0));
                    pos = this.node.convertToNodeSpaceAR(pos);
                    this.jianglibian.node.position = pos;
                    this.jianglibian.setAnimation(0, "Map_jiangliban", false);
                    this.jianglibian.setCompleteListener(()=>{
                        this.jianglibian.setCompleteListener(null);
                        this.jianglibian.node.active = false;
                        this.fishMulti.string = "X" + this._collectGame.itemCnt[2];
                    });
                });

                await cc.vv.gameData.awaitTime(2);

                await this.popDialog(2);

                this.cutSceneFish(true);

                await cc.vv.gameData.awaitTime(1.5);

                let pickgameScript = this.pickGame.getComponent("PoliticalStrategist_PickGame");
                this.pickGame.active = true;
                await pickgameScript.startPick(this._collectGame);
                this._collectGame = pickgameScript.getCollectGame();

                await cc.vv.gameData.awaitTime(0.5);

                this.cutSceneFish(false);

                await cc.vv.gameData.awaitTime(1.5);

                this.pickGame.active = false;

                await cc.vv.gameData.awaitTime(1);

                this.popResult(3);
            }
        }
    },

    getWinCoin() {
        return this._finalWinCoin;
    },

    cutSceneSanchaji(needMove) {
        Global.SlotsSoundMgr.playEffect("wheelTransition");
        let sanchaji = cc.find("sanchaji", this.node.parent);
        sanchaji.active = true;
        if (needMove) {
            let position = this.role.convertToWorldSpaceAR(cc.v2(0, 0));
            position = this.node.parent.convertToNodeSpaceAR(position);
            sanchaji.position = position;
            cc.tween(sanchaji)
                .to(0.3, {position: cc.v2(0, 0)})
                .start();
        }

        sanchaji.getComponent(sp.Skeleton).setAnimation(0, "sanchaji_guochang", false);
        sanchaji.getComponent(sp.Skeleton).setCompleteListener(()=>{
            sanchaji.getComponent(sp.Skeleton).setCompleteListener(null);
            sanchaji.active = false;
        });
    },

    cutSceneFish(needMove) {
        Global.SlotsSoundMgr.playEffect("koiTransition");
        let fish = cc.find("fish", this.node.parent);
        fish.active = true;
        if (needMove) {
            let position = this.role.convertToWorldSpaceAR(cc.v2(0, 0));
            position = this.node.parent.convertToNodeSpaceAR(position);
            fish.position = position;
            cc.tween(fish)
                .to(0.3, {position: cc.v2(0, 0)})
                .start();
        }

        fish.getComponent(sp.Skeleton).setAnimation(0, "liyu_guochang", false);
        fish.getComponent(sp.Skeleton).setCompleteListener(()=>{
            fish.getComponent(sp.Skeleton).setCompleteListener(null);
            fish.active = false;
        });
    },

    async chooseBox() {
        Global.SlotsSoundMgr.playEffect("VO_choose_your_final_prize_EN");
        this.boxSelect.active = true;
        this.boxSelectBlackBg.opacity = 0;
        cc.tween(this.boxSelectBlackBg)
            .to(0.5, {opacity: 200})
            .start();

        this.boxSelectChooseBoard.opacity = 0;
        cc.tween(this.boxSelectChooseBoard)
            .to(0.5, {opacity: 255})
            .start();

        this.boxLevelPrize.y = 0;
        for (let child of this.boxLevelPrize.children) {
            child.color = cc.Color.WHITE;
            for (let child1 of child.children) {
                child1.color = cc.Color.WHITE;
            }
        }
        cc.find("parent", this.boxLevelPrize).opacity = 0;
        this.boxLevelPrizeCoin.string = Global.FormatNumToComma(this._collectGame.roundInfo.options.levelPrize);
        cc.tween(this.boxLevelPrize)
            .by(0.5, {y: 250})
            .start();
        cc.tween(cc.find("parent", this.boxLevelPrize))
            .to(0.5, {opacity: 255})
            .start();

        this.boxMysteryPrize.y = 0;
        for (let child of this.boxMysteryPrize.children) {
            child.color = cc.Color.WHITE;
            for (let child1 of child.children) {
                child1.color = cc.Color.WHITE;
            }
        }
        cc.find("parent", this.boxMysteryPrize).opacity = 0;
        cc.find("parent/between_node", this.boxMysteryPrize).active = true;
        cc.find("parent/finish_node", this.boxMysteryPrize).active = false;
        this.boxMysteryPrizeMinCoin.string = Global.FormatNumToComma(this._collectGame.roundInfo.options.min);
        this.boxMysteryPrizeCoin.string = Global.FormatNumToComma(this._collectGame.roundInfo.options.min);
        this.boxMysteryPrizeMaxCoin.string = Global.FormatNumToComma(this._collectGame.roundInfo.options.max);
        cc.tween(this.boxMysteryPrize)
            .by(0.5, {y: -250})
            .start();
        cc.tween(cc.find("parent", this.boxMysteryPrize))
            .to(0.5, {opacity: 255})
            .start();

        await cc.vv.gameData.awaitTime(0.5);

        this.boxLevelPrize.on(cc.Node.EventType.TOUCH_END, ()=>{
            this.boxLevelPrize.off(cc.Node.EventType.TOUCH_END);
            this.boxMysteryPrize.off(cc.Node.EventType.TOUCH_END);
            this.reqChooseBox(1);
        });

        this.boxMysteryPrize.on(cc.Node.EventType.TOUCH_END, ()=>{
            this.boxLevelPrize.off(cc.Node.EventType.TOUCH_END);
            this.boxMysteryPrize.off(cc.Node.EventType.TOUCH_END);
            this.reqChooseBox(2);
        });
    },

    async reqChooseBox(index) {
        Global.SlotsSoundMgr.playEffect("chestClick");
        let reqdata = {rtype:5, choiceId: index};
        let result = await cc.vv.gameData.reqSubGame(reqdata);
        if (result.code === 200) {
            this._collectGame = result.data.collectGame;
            cc.vv.gameData.getDeskInfo().collectGame = result.data.newCollectGame;
            if (result.data.choiceId === 1) {
                // 直接选择了奖励
                let spine = cc.find("spine", this.boxLevelPrize).getComponent(sp.Skeleton);
                spine.node.active = true;
                spine.setAnimation(0, "bx_click", false);
                spine.setCompleteListener(()=>{
                    spine.setCompleteListener(null);
                    spine.node.active = false;
                });

                for (let child of this.boxMysteryPrize.children) {
                    child.color = cc.Color.GRAY;
                    for (let child1 of child.children) {
                        child1.color = cc.Color.GRAY;
                    }
                }

                await cc.vv.gameData.awaitTime(1);
            } else {
                for (let child of this.boxLevelPrize.children) {
                    child.color = cc.Color.GRAY;
                    for (let child1 of child.children) {
                        child1.color = cc.Color.GRAY;
                    }
                }

                let spine = cc.find("spine", this.boxMysteryPrize).getComponent(sp.Skeleton);
                spine.node.active = true;
                spine.setAnimation(0, "bx_click", false);
                spine.setCompleteListener(()=>{
                    spine.setCompleteListener(null);
                    spine.node.active = false;
                });

                cc.find("parent/between_node", this.boxMysteryPrize).active = false;
                cc.find("parent/finish_node", this.boxMysteryPrize).active = true;
                await cc.vv.gameData.awaitTime(0.5);
                Global.SlotsSoundMgr.playEffect("chestNumbr");
                Global.doRoallNumEff(this.boxMysteryPrizeCoin.node, this._collectGame.roundInfo.options.min,
                    this._collectGame.roundInfo.options.final, 3, ()=>{
                        Global.SlotsSoundMgr.playEffect("chestPrz");
                    }, null, 0, true);

                await cc.vv.gameData.awaitTime(3);
                spine.node.active = true;
                spine.setAnimation(0, "Num_end", false);
                spine.setCompleteListener(()=>{
                    spine.setCompleteListener(null);
                    spine.node.active = false;
                });

                await cc.vv.gameData.awaitTime(1);
            }

            this.boxSelect.active = false;
            this.popResult(1);
        }
    },

    /**
     * 弹框
     * @param type 1进入sanchaji游戏  2进入fish游戏
     */
    async popDialog(type) {
        return new Promise(async (success)=>{
            Global.SlotsSoundMgr.playEffect("mapbegain");
            this.dialogNode.active = true;
            let parent = cc.find("enter_sanchaji", this.dialogNode);
            if (type === 1) {
                parent = cc.find("enter_sanchaji", this.dialogNode);
            } else if (type === 2) {
                parent = cc.find("enter_fish", this.dialogNode);
            }
            parent.active = true;
            parent.scale = 0;
            cc.tween(parent)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            await cc.vv.gameData.awaitTime(0.5);

            let btn_start = cc.find("btn_start", parent);
            btn_start.off("click");
            let func  = async ()=>{
                btn_start.off("click");
                Global.SlotsSoundMgr.playEffect("button");

                cc.tween(parent)
                    .to(0.5, {scale: 0}, {easing: "backIn"})
                    .call(()=>{
                        this.dialogNode.active = false;
                        parent.active = false;
                        success();
                    })
                    .start();
            }
            cc.vv.gameData.checkAutoPlay(btn_start, func);
            btn_start.on("click", async () => {
                btn_start.stopAllActions();
                await func();
            });
        });
    },

    /**
     * 根据结束的方式
     * @param type 1box 2pearl 3sanchaji
     * @returns {Promise<void>}
     */
    async popResult(type) {
        this.resultNode.active = true;
        this.resultBoxEnd.active = false;
        this.resultPearlEnd.active = false;
        this.resultSanchajiEnd.active = false;

        Global.SlotsSoundMgr.playEffect("mapend");

        let dialog = cc.find("parent", this.resultNode);
        dialog.scale = 0;
        cc.tween(dialog)
            .to(0.5, {scale: 1}, {easing: "backOut"})
            .start();

        cc.find("yifenkuang/coin", dialog).getComponent(cc.Label).string =
            Global.FormatNumToComma(this._collectGame.roundInfo.winCoin);

        if (type === 1) {
            this.resultBoxEnd.active = true;
            cc.find("level", this.resultBoxEnd).getComponent(cc.Label).string = this._collectGame.level;
            cc.find("base_award", this.resultBoxEnd).getComponent(cc.Label).string =
                Global.formatNumShort(this._collectGame.roundInfo.baseCoin);
            cc.find("level_prize", this.resultBoxEnd).getComponent(cc.Label).string =
                Global.formatNumShort(this._collectGame.roundInfo.winCoin - this._collectGame.roundInfo.baseCoin);
        } else if (type === 2) {
            this.resultPearlEnd.active = true;
            cc.find("base_award", this.resultPearlEnd).getComponent(cc.Label).string =
                Global.formatNumShort(this._collectGame.roundInfo.baseCoin);
            cc.find("multiplier", this.resultPearlEnd).getComponent(cc.Label).string = this._collectGame.roundInfo.mult;
        } else if (type === 3) {
            this.resultSanchajiEnd.active = true;
            cc.find("base_award", this.resultSanchajiEnd).getComponent(cc.Label).string =
                Global.formatNumShort(this._collectGame.roundInfo.baseCoin);
            cc.find("mini_game_bonus", this.resultSanchajiEnd).getComponent(cc.Label).string =
                this._collectGame.roundInfo.miniGame.winCoin;
        }

        this._finalWinCoin = this._collectGame.roundInfo.winCoin;

        await cc.vv.gameData.awaitTime(0.5);

        this.btnCollect.off("click");
        let func = async ()=>{
            this.btnCollect.off("click");

            cc.tween(dialog)
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .call(()=>{
                    this.resultNode.active = false;

                    this._endCallback();
                    this._endCallback = null;
                })
                .start();
        }
        cc.vv.gameData.checkAutoPlay(this.btnCollect, func);
        this.btnCollect.on("click", async () => {
            this.btnCollect.stopAllActions();
            await func();
        });
    },

    resetRole() {
        this.role_prizeBooster.node.active = false;
        this.role_pearl.node.active = false;
        this.role_box.node.active = false;
        this.role_sanchaji.node.active = false;
        this.role_fish.node.active = false;
        this.role_coin.node.active = false;
    },

    /**
     * 根据位置显示箭头，从1开始
     * @param index
     */
    showArrow(index) {
        this._canGo = true;
        this.arrow_up.active = index > 6;
        this.arrow_down.active = index < 55;
        this.arrow_left.active = index % 6 !== 1;
        this.arrow_right.active = index % 6 !== 0;
    },

    hideArrow() {
        this._canGo = false;
        this.arrow_up.active = false;
        this.arrow_down.active = false;
        this.arrow_left.active = false;
        this.arrow_right.active = false;
    },

    /**
     * boardInfo = {}, // 棋盘对应的信息{isOpen=false, coin=1000, type=CollectGameItemType}
     * @param index
     * @param info
     */
    showInfo(index, info) {
        let point = cc.find("point_" + index, this.detail);
        cc.find("bg", point).active = !info.isOpen;
        cc.find("pearl", point).active = info.type === CollectGameItemType.Pearl;
        cc.find("box", point).active = info.type === CollectGameItemType.Mystery;
        cc.find("trident", point).active = info.type === CollectGameItemType.DragonBlade;
        cc.find("prize_booster", point).active = info.type === CollectGameItemType.PrizeBooster;
        cc.find("coin", point).active = info.type === CollectGameItemType.Coin;
        if (info.type === CollectGameItemType.Coin) {
            cc.find("coin", point).getComponent(cc.Label).string = Global.formatNumShort(info.coin, 0);
        }
        cc.find("fish", point).active = info.type === CollectGameItemType.GoldenKoi;
    },
});